MLX_CORE_STUB = 'float32 = "float32"\nlimits = {}\n\n\ndef set_memory_limit(value):\n    limits["memory"] = value\n    return 0\n\n\ndef set_cache_limit(value):\n    limits["cache"] = value\n    return 0\n\n\ndef get_active_memory():\n    return 0\n\n\ndef get_cache_memory():\n    return 0\n\n\ndef get_peak_memory():\n    return 0\n\n\ndef eval(value):\n    return None\n\n\nclass Array:\n    def __init__(self, values):\n        self.values = values\n\n    def __getitem__(self, key):\n        if key is None:\n            return Array([self.values])\n        if isinstance(key, Array):\n            return Array([self.values[int(index)] for index in key.values])\n        return Array(self.values[key])\n\n    def astype(self, dtype):\n        return self\n\n    def tolist(self):\n        return self.values\n\n\ndef array(values):\n    return Array(values)\n'
MLX_LM_UTILS_STUB = 'import mlx.core\n\nPICK = 0\nSYMBOLS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"\n\n\nclass Body:\n    def __call__(self, ids):\n        return [mlx.core.Array([[0.0]] * len(ids.values[0]))]\n\n\nclass Language:\n    model = Body()\n\n    def lm_head(self, rows):\n        return mlx.core.Array([{ord(symbol): (10.0 if index == PICK else 0.0) for index, symbol in enumerate(SYMBOLS)} for _ in rows.values])\n\n\nclass Model:\n    language_model = Language()\n\n\ndef load_model(path):\n    if set(mlx.core.limits) != {"memory", "cache"}:\n        raise RuntimeError("the model loaded before MLX memory limits were set")\n    return Model(), {}\n'
MLX_LM_MAIN_STUB = 'import os\nimport sys\n\narguments = sys.argv[1:]\ntarget = arguments[arguments.index("--mlx-path") + 1]\nos.makedirs(target, exist_ok=True)\nfor name in ("config.json", "tokenizer.json"):\n    with open(os.path.join(target, name), "w") as handle:\n        handle.write("{}")\n'
TRANSFORMERS_STUB = 'MARKER = 100000\n\n\nclass Tokenizer:\n    def convert_tokens_to_ids(self, token):\n        return MARKER\n\n    def apply_chat_template(self, messages, **options):\n        return messages[1]["content"] + messages[2]["content"]\n\n    def __call__(self, text, add_special_tokens=False):\n        ids = [ord(char) % 200 for char in text.replace("<decision>", "")]\n        return {"input_ids": ids + [MARKER] * text.count("<decision>")}\n\n    def encode(self, symbol, add_special_tokens=False):\n        return [ord(symbol)]\n\n\nclass AutoTokenizer:\n    @staticmethod\n    def from_pretrained(path, local_files_only=False):\n        return Tokenizer()\n'
HUGGINGFACE_HUB_STUB = 'import os\n\n\ndef snapshot_download(repo, revision=None, allow_patterns=None):\n    path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "source")\n    os.makedirs(path, exist_ok=True)\n    return path\n'
